@Service
public class OrderService {

    @Autowired
    private OrderRepository orderRepository;

    // Self-injection workaround to access the proxy
    @Autowired
    private OrderService self;

    public void processOrder(Order order) {
        // BAD: This will NOT start a transaction
        // this.doTransactionalWork(order);

        // GOOD: Calling via the self-proxy routes through the interceptor
        self.doTransactionalWork(order);
    }

    @Transactional
    public void doTransactionalWork(Order order) {
        orderRepository.save(order);
    }
}
